#include <Wire.h>
#include <LiquidCrystal_I2C.h>

LiquidCrystal_I2C lcd(0x27, 16, 2);

void setup() {
  Serial.begin(9600);
  lcd.init();
  lcd.backlight();
  lcd.setCursor(0, 0);
  lcd.print("Waiting for PC..");
}

void loop() {
  if (Serial.available()) {
    // Читаем первую строку (CPU)
    String cpuLine = Serial.readStringUntil('\n');
    // Читаем вторую строку (GPU)
    String gpuLine = Serial.readStringUntil('\n');

    cpuLine.trim();
    gpuLine.trim();

    if (cpuLine.length() > 0) {
      lcd.clear();
      lcd.setCursor(0, 0);
      lcd.print(cpuLine);
      lcd.setCursor(0, 1);
      lcd.print(gpuLine);
    }
  }
}
